window.VD=window.VD||{};window.VD["audi/e-tron-ge"]={"e-tron-ge-activate-360-degree-park-assist-display-camera":"<p><strong>Purpose:</strong> Automatically sets the display of activated parking assistance as a 360-degree panoramic view if the view camera system is installed.  </p>\n<p><br/><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port or your OBDeleven unit.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program or the OBDeleven app.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong> Adaptation – 10 </strong>”.</p>\n<p><strong>5</strong> – Select<em>“Visual parking aid display</em>” / “Optische Anzeige für Einparkhilfe” <strong>channel</strong> </p>\n<p>Set value to “OPS+360”.</p>\n<p>Restart the MMI: long press NAV/MAP + rotary pushbutton + RADIO</p>","e-tron-ge-activate-g-meter":"<p><strong>Purpose</strong>: Adds the G-Meter (Accelerometer) to the Virtual Cockpit screen.  <br/><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Display Acceleration</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/accelerationdisplay-4bb736e5.webp\"/></figure>","e-tron-ge-daytime-running-lights-drl-on-off-via-mmi":"<p><strong>Purpose:</strong> to activate/deactivate the daytime running lights (DRL) from the MMI.  </p>\n<p>ATTENTION to your country’s regulations and technical inspection for daytime running lights!<br/>However, if you’re coding in your car to avoid using too much of your battery, this is a good solution…</p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click “<strong>Coding – 07</strong>.”<br/><br/><strong>5</strong> – Select byte <strong>2</strong>, check bit <strong>1</strong> “drl_mmi”.</p>\n<p>OBDELEVEN: “DRL_MMI” active</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/drlmmiaudi-c12a3aa1.webp\"/></figure>","e-tron-ge-delete-belt-alarm":"<p><strong>Purpose:</strong> to suppress the audible alarm and warning light in the Virtual Cockpit when driving without a seatbelt.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte <strong>0</strong>:<br/>Bit <strong>2-4</strong>: select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<p><strong><em>OR</em></strong></p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Deactivate</strong> <strong>Seat belt warning”</strong> / <strong>“</strong> <strong>Désactiver l’avertissement de ceinture”.</strong> <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select<strong>“Oui</strong>” /<strong>“Yes”</strong> and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8U0_920_940_Module17_Adaptation_desactivate_seat_b-77d3b532.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","e-tron-ge-disable-the-am-frequency-on-the-mmi":"<p><strong>Purpose:</strong> Allows you to disable AM radio on the MMI (AM radio is rarely used, unlike FM radio). </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1 “AM_disable” to 1 </strong> </p>\n<figure>\n</figure>","e-tron-ge-desactiver-le-deverrouillage-automatique-des-portes-avec-dsg-sur-p":"<p><strong>Purpose:</strong> Disables the feature that automatically unlocks all doors when the DSG automatic transmission is shifted to the “P” position.</p>\n<p><strong>Procedure: </strong><br/><strong>1 –</strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2 –</strong> Switch on the ignition and run the VCDS program.</p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong> then click on <strong>” <strong>46 – Central Module Comfort System</strong> “</strong> .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Clear the bit  <strong>” </strong><strong>automatic_unlock_nar”</strong> </p>","e-tron-ge-enable-automatic-window-lowering":"<p><strong>Purpose:</strong> Allows the windows to be slightly ajar when the driver’s or passenger’s door is open. When a window is lowered, the cabin is no longer completely sealed, allowing the doors to be closed gently without having to slam them shut. (Windows Auto Drop)    <br/><br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>3</strong>“<br/>. Then uncheck bit “<strong>1</strong>“: “<strong>short_drop,active</strong>“<br/><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>42 – Driver’s Door</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>3</strong>“<br/>. Then uncheck bit “<strong>1</strong>“: “<strong>short_drop,active</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Window_Auto_Drop_Audi-1024x333-72c26167.webp\"/></figure>","e-tron-ge-enable-mmi-sound-at-startup":"<p><strong>Purpose:</strong> Enables the startup sound (welcome sound), which plays when the MMI or the vehicle is turned on.  </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Vehicle configuration – vehicle_readiness_sound</strong>“<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>","e-tron-ge-enable-the-hidden-mmi-menu":"<p><strong>Purpose</strong>: to activate the MMI’s hidden menu (Hidden Menu / Green Menu / Menu Engineering).  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>5F – Electrical Information</strong></strong>“.</p>\n<p><strong>4</strong> – Click on ” <strong>Adaptation – 10</strong>“.</p>\n<p><strong>5</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>S12345</strong>“</p>\n<p><strong>6</strong> – Select “<em><strong>Developer Test Mode</strong>” or </em> <em>“<strong>Developer Mode</strong>” or </em><strong><em>“Entwicklermodus”</em></strong> and then enable it.</p>\n<p><em>No need to restart the MMI.</em></p>\n<p><em>To open the hidden menu with NAV/MAP (or CAR) and RADIO. First press and hold NAV/MAP (or CAR), then press RADIO and wait 5 seconds. </em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/A4-Hidden-Menu-ec3628a6.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/A4-Hidden-Menu2-0030a834.webp\"/></figure>\n<p><strong><a href=\"#/t/access-the-audi-red-engineering-menu\">–&gt; To access the Audi Red Engineering menu</a></strong></p>","e-tron-ge-heated-seat-settings":"<p><strong>Purpose:</strong> Used to adjust the seat heating temperature, you can increase or decrease the heating level of all or part of the seat by up to 5 degrees Celsius to obtain the optimum temperature setting for you.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fine adjustment of seat heating level 1</strong>” or “Sitzheizung Feineinstellung Stufe 1”.</p>\n<p>Then levels <strong>2</strong> and <strong>3</strong> <em>(Heated seat power)</em><br/><br/> 6 – On this same page, there is a second drop-down menu at the bottom of the page.<br/>Here, select the range of values: -5 to +5 (degrees Celsius) relative to the base temperature, then confirm.</p>","e-tron-ge-lap-timer":"<p><strong>Purpose:</strong> to add the stopwatch to the Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Lap Timer active</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>\n<p><br/><strong>Alternative method if the 1st doesn’t work!! :</strong><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Lap counter</strong>”.<br/><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Display</strong>” and confirm.</p>\n<figure>\n</figure>","e-tron-ge-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Works with Virtual Cockpit) (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep (Stading) active</strong>” or “Staging”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>","e-tron-ge-pair-a-second-phone-via-bluetooth":"<p><strong>Purpose:</strong> Allows you to connect two phones via Bluetooth simultaneously to the MMI if you do not have the Audi Phone Box option. <br/><br/><br/><br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong><strong>Vehicle configuration – Support_second_phone</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<p><em>Restart MMI</em></p>","e-tron-ge-rear-lights-activated-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated. <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Coding – 07</strong>“.</p>\n<p><strong>5</strong> – Select byte <strong>2</strong>, set bit <strong>3 ” </strong>sl_at_drl”</p>\n<p>OBDELEVEN: “SL_AT_DRL” is enabled</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/drlaudi-f9e7108c.webp\"/></figure>","e-tron-ge-unlocking-the-menus-while-driving":"<p><strong>Purpose:</strong> Allows you to unlock certain multimedia system menus while driving, and to enable text entry for CarPlay and Android Auto, which are normally disabled when the vehicle is in motion.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>Line 1 (Menu)</strong><br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Locked menu contents</strong>” <strong>(FB CAR, media, and nav)</strong><br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>non_blocked</strong>” and then confirm.</p>\n<p><strong>Line 2</strong><br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>NHSTA Properties</strong>“<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>not_activated</strong>” and then confirm.</p>\n<p><strong>Line 3 (CarPlay)</strong><br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>nhtsa_limitation_switches_for_carplay_no_softKeyboard</strong>“<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down<br/>the page.<br/>From this menu, select “<strong>not_activated</strong>” and then confirm.</p>\n<p><strong>Line 4 (Android Auto)</strong><br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>nhtsa_limitation_switches_for_androidauto_no_text_input</strong>“<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>not_activated</strong>” and then confirm.</p>","e-tron-ge-ventilated-seat-settings":"<p><strong>Purpose:</strong> Allows you to fine-tune seat ventilation, you can increase or decrease all respective seat ventilation levels by up to 10% compared to factory delivery to obtain the optimum amount of ventilation for you.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (Front seats):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fine adjustment of seat ventilation level 1</strong>” / “Sitzlüftung Feineinstellung Stufe 1”.</p>\n<p>Then levels <strong>2</strong> and <strong>3</strong> <em>(Power of ventilated seats)</em><br/><br/> 6 – On this same page, there is a second drop-down menu, but towards the bottom of the page.<br/>On this, choose the range of values: -10 to +10 (% – per cent) in relation to the basic ventilation speed, then validate.</p>\n<p><strong>Line 2 (Rear seats):</strong><br/><br/> 3 – Click on<strong>“Select</strong>” then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/> 4 – Click on<strong>“Adaptation – 10</strong>”.<br/><br/> 5 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fine adjustment of rear seat ventilation level 1</strong>” / “Sitzlüftung hinten Feineinstellung Stufe 1”.</p>\n<p>Then levels <strong>2</strong> and <strong>3</strong> <em>(Power of <em>ventilated</em> seats)</em><br/><br/> 6 – On this same page there is a second drop-down menu, but towards the bottom of the page.<br/>On this, choose the range of values: -10 to +10 (% – per cent) in relation to the base ventilation speed, then validate.</p>","e-tron-ge-wireless-carplay-activation":"<p><strong>Purpose</strong>: Enables Apple CarPlay Wireless and Google Android Auto Wireless to be activated without the need for a USB cable.  </p>\n<p><em><em>The vehicle must have an enabled USB wired CarPlay connection (Audi Smartphone Interface) and a MIB2 Plus with MH2p system must be </em>running firmware P2470 or higher (MH2p_ER_AUG35_P2470) or MIB3<em>.</em> </em><br/><em>Before you start, disassociate/delete all Apple devices from CarPlay and Bluetooth (including deleting the car if already paired from the Apple device itself – settings/general/CarPlay).</em></p>\n<p><strong>Watch out! There are 7 lines of coding to do here. </strong></p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or OBDeleven.<br/><br/>2 – Switch on the ignition and run the VCDS program. or OBDeleven.</p>\n<p><strong>Line 1 (Wifi):</strong><br/><br/><br/> 3 – Click on ” <strong>Select</strong> ” then click on “Select”.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Choose Channel <em>:</em> <em>“</em>Vehicle configuration – wlan_5ghz_switch<em>“.</em></p>\n<p><em>Set value to “ON</em></p>\n<p><strong>Line 2 (Wifi):</strong><br/><br/><br/> 3 – Click on ” <strong>Select</strong> ” then click on “Select”.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Choisir Canal <em>:</em> <em>“</em>Véhicule configuration – WiFi_Client_HMI<em>“</em></p>\n<p><em>Set value to “ON</em></p>\n<p><strong>Line 3 (Apple Carplay):</strong><br/><br/><br/>3 – Click on ” <strong>Select</strong> ” then click on “Select”.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Choose Channel <em>:</em> <em>“Vehicle configuration – Apple_DIO_Wireless”.</em></p>\n<p><em><em>Set value to “ON</em></em></p>\n<p>Line 4 (Apple Carplay):<br/><br/><br/>3 – Click on ” Select ” then click on “Select”.5F – Information Electr.” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Choose Channel <em>:</em> <em>“Vehicle configuration – Apple_DIO”.</em></p>\n<p><em><em>Set value to “ON</em></em></p>\n<p><strong>Line 5 (Android Auto):</strong><br/><br/><br/>3 – Click on ” <strong>Select</strong> ” then click on “Select”.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Select Channel <em>:</em> <em>“</em>Vehicle configuration – Google_GAL_Wireless<em>“.</em></p>\n<p><em><em>Set value to “ON</em></em></p>\n<p><strong>Line 6 (Android Auto):</strong><br/><br/><br/>3 – Click on ” <strong>Select</strong> ” then click on “Select”.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Choose Channel <em>:</em> <em>“</em>Vehicle configuration – Google_GAL<em>“.</em></p>\n<p><em><em>Set value to “ON</em></em></p>\n<p><strong>Line 7 (Android Auto):</strong><br/><br/><br/>3 – Click on ” <strong>Select</strong> ” then click on “Select”.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 </strong>– Select Channel <em>:</em> <em>“</em>Vehicle configuration – MirrorLink<em>“.</em></p>\n<p><em><em>Set value to “ON</em></em></p>\n<hr/>\n<p>Restart <strong>MIB3</strong>, reset MMI (hold down volume control for at least 10-15 seconds)</p>\n<p><em>Don’t plug your Apple device into the USB port!</em></p>\n<p>Make sure the WIFI access point is enabled in the MMI settings.<br/>On your iPhone under Settings -&gt; Wi-Fi, your car should appear with ***_5GHZ. <br/>Pair your Apple device with Bluetooth, it should now ask you if you want to activate CarPlay.<br/>If not, delete the pairing, first connect to the car’s Wi-Fi from the Apple device, then retry pairing via Bluetooth.</p>"};
